export function slugify(text, { maxLength } = {}) {
  const slug = text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (maxLength === undefined || slug.length <= maxLength) return slug;
  const cut = slug.lastIndexOf("-", maxLength);
  return cut > 0 ? slug.slice(0, cut) : slug.slice(0, maxLength);
}

