test("collapses punctuation and spaces into single dashes", () => {
  assert.equal(slugify("  Hello, World!  "), "hello-world");
});

test("trims at the last word boundary that fits maxLength", () => {
  assert.equal(slugify("Release notes for October", { maxLength: 16 }), "release-notes");
});

test("cuts a first word longer than maxLength", () => {
  assert.equal(slugify("Supercalifragilistic", { maxLength: 5 }), "super");
});

